css:
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) {
  position: relative;
  isolation: isolate;
  overflow: clip !important;
}
[data-workspace-area="conversation"]:not([data-side-chat-pane] *) > * {
  position: relative;
  z-index: 1;
}
[data-chat-header]:not([data-side-chat-pane] *) {
  position: relative;
}

/* Editorial crimson notebook margin rule (calm / static) */
[data-workspace-area="conversation"]:not([data-side-chat-pane] *)::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 28px;
  width: 1px;
  pointer-events: none;
  z-index: 0;
  background: rgba(158, 59, 59, 0.28);
}
.dark [data-workspace-area="conversation"]:not([data-side-chat-pane] *)::before {
  background: rgba(201, 106, 106, 0.25);
}

/* Crimson bookmark flag when a subagent is running (calm / static) */
[data-workspace-area="conversation"]:not([data-side-chat-pane] *):has([data-subagent-group]:not([data-side-chat-pane] *) .text-info, [data-v2-item-type="subagent"]:not([data-side-chat-pane] *) .bg-info)::after {
  content: "";
  position: absolute;
  top: 0;
  right: 22px;
  width: 8px;
  height: 16px;
  background: #9e3b3b;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 50% 72%, 0 100%);
  pointer-events: none;
  z-index: 2;
}
.dark [data-workspace-area="conversation"]:not([data-side-chat-pane] *):has([data-subagent-group]:not([data-side-chat-pane] *) .text-info, [data-v2-item-type="subagent"]:not([data-side-chat-pane] *) .bg-info)::after {
  background: #c96a6a;
}

[data-user-message-bubble]:not([data-side-chat-pane] *) {
  border-left: 3px solid #9e3b3b !important;
}
.dark [data-user-message-bubble]:not([data-side-chat-pane] *) {
  border-left-color: #c96a6a !important;
}

[data-slot="composer-host"]:not([data-side-chat-pane] *) {
  border-bottom: 2px solid transparent !important;
  transition: border-color 200ms ease;
}
[data-slot="composer-host"]:not([data-side-chat-pane] *):focus-within {
  border-bottom-color: #9e3b3b !important;
}

[data-chat-header]:not([data-side-chat-pane] *)::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3px;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(158, 59, 59, 0.65) 0 var(--mn-folio, 12%), transparent var(--mn-folio, 12%)),
    repeating-linear-gradient(90deg, #9e3b3b 0 2px, transparent 2px 6px);
  background-size: 100% 1px, var(--mn-tallies, 0px) 3px;
  background-repeat: no-repeat;
  background-position: left bottom, right 16px bottom;
}
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-timeline-row-kind]:nth-child(10)) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-folio: 30%; }
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-timeline-row-kind]:nth-child(20)) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-folio: 54%; }
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-timeline-row-kind]:nth-child(35)) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-folio: 78%; }
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-timeline-row-kind]:nth-child(50)) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-folio: 95%; }

body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-v2-item-type="subagent"]:nth-child(1) .bg-success) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-tallies: 6px; }
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-v2-item-type="subagent"]:nth-child(2) .bg-success) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-tallies: 12px; }
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-v2-item-type="subagent"]:nth-child(3) .bg-success) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-tallies: 18px; }
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-v2-item-type="subagent"]:nth-child(4) .bg-success) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-tallies: 24px; }
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-v2-item-type="subagent"]:nth-child(5) .bg-success) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-tallies: 30px; }
body:has([data-workspace-area="conversation"]:not([data-side-chat-pane] *) [data-v2-item-type="subagent"]:nth-child(6) .bg-success) [data-chat-header]:not([data-side-chat-pane] *)::after { --mn-tallies: 36px; }
